<template><dialog ref="modal" class="social-dialog celebration" @cancel.prevent="close"><span class="match-heart" aria-hidden="true">♥</span><h2>축하해요<br/>매칭됐어요!</h2><p>서로의 마음이 닿았어요.</p><button class="primary" @click="go">확인하러 가기</button><button @click="close">닫기</button></dialog></template>
<script setup>
import {ref,onMounted,onUnmounted,watch} from 'vue';import {useRouter,useRoute} from 'vue-router';import api from '../api/api';import {getToken} from '../utils/auth';
const modal=ref(),router=useRouter(),route=useRoute();let timer,current,loading=false,disposed=false;const shown=new Set();let session='';
async function poll(){const token=getToken();if(!token||!/^\/(today|matches|chats|members|profile|settings|credits|notifications)(\/|$)/.test(route.path)||document.hidden||modal.value?.open||loading)return;if(session!==token){shown.clear();session=token;}loading=true;try{const {data}=await api.get('/social/inbox');if(disposed||getToken()!==token)return;const n=data.find(n=>n.eventKey?.startsWith('MATCH:')&&!n.seen&&!shown.has(n.id));if(n){current=n;shown.add(n.id);modal.value.showModal();}}catch{}finally{loading=false;}}
async function close(){modal.value.close();if(current){const n=current;current=null;try{await api.post('/social/inbox/read',[n.id]);window.dispatchEvent(new Event('notifications-changed'));}catch{shown.delete(n.id);}}}
function go(){const link=current?.link||'/matches';close();router.push(link);}
watch(()=>route.path,()=>{if(route.path.startsWith('/admin'))modal.value?.close();else poll();});onMounted(()=>{poll();timer=setInterval(poll,10000);window.addEventListener('notifications-changed',poll);});onUnmounted(()=>{disposed=true;clearInterval(timer);window.removeEventListener('notifications-changed',poll);});
</script><style scoped>.celebration{text-align:center;padding:34px 24px;max-width:340px}.match-heart{display:grid;place-items:center;margin:0 auto 22px;width:84px;height:84px;border-radius:28px;background:#fff0e7;color:#d56f4e;font-size:42px;animation:heart-in .4s ease-out}.celebration h2{font-size:25px;line-height:1.4}.celebration p{color:#947568;font-size:13px;margin-bottom:25px}.celebration button{display:block;width:100%;margin-top:10px}@keyframes heart-in{from{transform:scale(.7);opacity:0}to{transform:scale(1);opacity:1}}@media(prefers-reduced-motion:reduce){.match-heart{animation:none}}</style>
